var DEFAULT_BRACKETS = [   // 美国联邦单身 2023（累进）
  {upTo:11000,  rate:0.10},
  {upTo:44725,  rate:0.12},
  {upTo:95375,  rate:0.22},
  {upTo:182100, rate:0.24},
  {upTo:231250, rate:0.32},
  {upTo:578125, rate:0.35},
  {upTo:Infinity, rate:0.37}
];
function computeTax(income, brackets){
  brackets=brackets||DEFAULT_BRACKETS;
  var tax=0, prev=0;
  for(var i=0;i<brackets.length;i++){
    var top=brackets[i].upTo, rate=brackets[i].rate;
    var taxable=Math.min(income, top) - prev;
    if(taxable>0) tax += taxable*rate;
    prev=top;
    if(income<=top) break;
  }
  return tax;
}
function marginalRate(income, brackets){
  brackets=brackets||DEFAULT_BRACKETS;
  for(var i=0;i<brackets.length;i++){ if(income<=brackets[i].upTo) return brackets[i].rate; }
  return brackets[brackets.length-1].rate;
}
function effectiveRate(income, brackets){ var t=computeTax(income,brackets); return income>0? t/income : NaN; }
var EXPORTS={ DEFAULT_BRACKETS:DEFAULT_BRACKETS, computeTax:computeTax, marginalRate:marginalRate, effectiveRate:effectiveRate };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TaxForgePure = EXPORTS; }
